h2 { font-family:'Merriweather', serif; font-size: clamp(24px, 3vw, 40px); margin:0 0 clamp(12px,1.4vw,18px); line-height:1.2; }
.subtitle { font-size: clamp(16px,1.8vw,26px); color:var(--muted); max-width: 90%; }
.small { font-size: clamp(12px,1.1vw,16px); color:var(--muted); }
.row { display:flex; gap: clamp(12px,1.5vw,22px); }
.card { background:var(--card); border:1px solid rgba(255,255,255,.15); border-radius:16px; padding: clamp(10px,1.2vw,18px); }
.bar-wrap { margin-top: clamp(8px,1vh,14px); display:grid; gap: clamp(8px,1vh,12px); }
.bar { display:grid; grid-template-columns: 200px 1fr auto; gap:10px; align-items:center; }
.label { font-size: clamp(14px,1.3vw,20px); }
