  border-radius:16px;
  border:1px solid rgba(255,255,255,.18);
  background:
  linear-gradient(90deg, transparent 36%, rgba(255,209,102,.35) 36.5%, transparent 37%),
  linear-gradient(90deg, transparent 49%, rgba(61,214,198,.35) 49.5%, transparent 50%),
  linear-gradient(90deg, transparent 62%, rgba(239,71,111,.35) 62.5%, transparent 63%),
