.net { display:grid; grid-template-columns: repeat(6, 1fr); gap:8px; align-content:start; }
.dot { width: clamp(22px,2.2vw,34px); aspect-ratio:1; border-radius:50%; display:grid; place-items:center; font-size: clamp(10px,.8vw,12px); font-weight:700; }
