        <tr><td>Measles</td><td>3,044</td><td>0.2</td><td>99.99%</td><td>2.5</td><td class="mark100">100%</td></tr>
        <tr><td>Smallpox</td><td>250</td><td>0</td><td class="mark100">100%</td><td>2.9</td><td class="mark100">100%</td></tr>
        <tr><td>Acute polio</td><td>141</td><td>0</td><td class="mark100">100%</td><td>10</td><td class="mark100">100%</td></tr>
        <tr><td>Pertussis</td><td>1,534</td><td>52</td><td>96.6%</td><td>30.8</td><td>99.7%</td></tr>
        <tr><td>Rubella</td><td>242</td><td>0.04</td><td>99.98%</td><td>0.09</td><td class="mark100">100%</td></tr>
        <tr><td>Hepatitis A</td><td>465</td><td>51</td><td class="warn">89%</td><td>0.5</td><td class="warn">88.7%</td></tr>
        <tr><td>Acute hepatitis B</td><td>273</td><td>44</td><td class="warn">83.9%</td><td>1</td><td class="warn">83.6%</td></tr>
        <tr><td>Pneumococcal</td><td>233</td><td>139</td><td class="warn">40.5%</td><td>24</td><td class="warn">31.3%</td></tr>
      </tbody>
    </table>
  </div></section>

  <section class="slide"><div class="content">
    <h2>Measles Cases Collapsed Across All 50 US States After Vaccine Mandates</h2>
